CREATE TABLE cap19_quality (row_id INTEGER PRIMARY KEY, product_code TEXT NOT NULL UNIQUE, stock_qty INTEGER NOT NULL CHECK (stock_qty >= 0), active INTEGER NOT NULL CHECK (active IN (0,1)));
INSERT INTO cap19_quality VALUES (1, 'P-100', 8, 1), (2, 'P-200', 0, 0);
CREATE INDEX idx_cap19_quality_active ON cap19_quality(active, product_code);
SELECT product_code, stock_qty FROM cap19_quality WHERE active = 1 ORDER BY product_code;

